from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, Table, TableStyle, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib import colors
from reportlab.lib.units import mm
from pathlib import Path

BASE=Path('/mnt/data/ai_desk_companion_cad')
OUT=BASE/'motion_revision_R1'
PDF=Path('/mnt/data/AI_Desk_Companion_CAD_and_Motion_Engineering_Report_R1.pdf')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='RTitle',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=23,leading=28,alignment=TA_CENTER,textColor=colors.HexColor('#172932'),spaceAfter=5))
styles.add(ParagraphStyle(name='RSub',parent=styles['Normal'],fontSize=10,leading=14,alignment=TA_CENTER,textColor=colors.HexColor('#53616c'),spaceAfter=12))
styles.add(ParagraphStyle(name='RH1',parent=styles['Heading1'],fontSize=15,leading=19,textColor=colors.HexColor('#174552'),spaceBefore=4,spaceAfter=7))
styles.add(ParagraphStyle(name='RH2',parent=styles['Heading2'],fontSize=11,leading=14,textColor=colors.HexColor('#176879'),spaceBefore=7,spaceAfter=4))
styles.add(ParagraphStyle(name='RB',parent=styles['BodyText'],fontSize=9,leading=13,spaceAfter=6))
styles.add(ParagraphStyle(name='RS',parent=styles['BodyText'],fontSize=7.6,leading=10,textColor=colors.HexColor('#46545d'),spaceAfter=4))
styles.add(ParagraphStyle(name='RWarn',parent=styles['BodyText'],fontSize=9,leading=13,textColor=colors.HexColor('#783e14'),backColor=colors.HexColor('#fff2e4'),borderColor=colors.HexColor('#e3bd96'),borderWidth=.5,borderPadding=7,spaceBefore=4,spaceAfter=8))
styles.add(ParagraphStyle(name='RCall',parent=styles['BodyText'],fontSize=9,leading=13,backColor=colors.HexColor('#eef4f5'),borderColor=colors.HexColor('#bed0d5'),borderWidth=.5,borderPadding=7,spaceBefore=3,spaceAfter=8))
def P(t,s='RB'): return Paragraph(t,styles[s])

def footer(canvas,doc):
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor('#ccd5d9')); canvas.line(18*mm,14*mm,192*mm,14*mm)
    canvas.setFont('Helvetica',7); canvas.setFillColor(colors.HexColor('#63717a'))
    canvas.drawString(18*mm,9*mm,'AI Desk Companion | CAD & Motion Engineering R1')
    canvas.drawRightString(192*mm,9*mm,f'Page {doc.page}')
    canvas.restoreState()

story=[]
story += [Spacer(1,7*mm),P('AI DESK COMPANION','RTitle'),P('CAD, Articulated Arm & Gripper Motion Report - Revision R1','RSub'),Spacer(1,3*mm)]
img=Image(str(OUT/'motion_pose_sheet.png'),width=166*mm,height=175*mm)
story += [img,Spacer(1,3*mm),P('<b>Revision scope:</b> Retains the selected two structural legs and broad feet; replaces the previous static arm shapes with separate shoulder links, elbow links, wrist/palm and open/closed pinch-gripper geometry. Includes discrete STEP poses and a parametric OpenSCAD animation source.','RB'),P('<b>Important status:</b> This is an articulated concept/packaging revision, not production-ready mechanism CAD. The animation demonstrates geometry movement, but does not prove collision-free travel, actuator torque, gripper force, reliability or safety.','RWarn'),PageBreak()]

story += [P('1. What moves in R1','RH1'),P('The current selected leg-and-foot design is a standing structure. The two legs are not powered, and the robot does not walk, roll or drive around a desk. The movement revision applies to the arms and hands only.','RB')]
pose_data=[['Motion','Shoulder pitch','Elbow relative','Gripper'],['Neutral','-25°','+40°','Open'],['Wave left/right','+45°','-55° on waving arm','Open'],['Point/reach','0°','0°','Open'],['Nudge pose','-20°','+55°','Open'],['Grip','-25°','+40°','Closed']]
t=Table([[P(str(c),'RS') for c in row] for row in pose_data],colWidths=[44*mm,35*mm,43*mm,34*mm],repeatRows=1)
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#174552')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#cbd5d9')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f4f7f8')]),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
story += [Spacer(1,2*mm),t,Spacer(1,4*mm),P('Each pose is exported as its own STEP file. STEP normally contains static solids, so the model uses OpenSCAD for the live interpolated preview and STEP snapshots for CAD review.','RB'),P('2. Joint architecture','RH1')]
joint_data=[['Joint','Motion axis','Proposed concept range','Count'],['Shoulder pitch','X axis; raises/lowers arm in Y-Z plane','-35° to +50°','1 per arm'],['Elbow pitch','X axis; relative angle to upper arm','-60° to +65°','1 per arm'],['Coupled gripper','Two jaw pivots around Z, one coupled actuator','Approx. 22.6 mm tip-center gap open; 5.6 mm closed','1 per hand'],['Head tilt','Not in R1 motion assembly','Requires hinge/dock redesign','0 in R1'],['Body locomotion','Not in R1','Structural legs/feet only','0 in R1']]
t=Table([[P(str(c),'RS') for c in row] for row in joint_data],colWidths=[34*mm,51*mm,73*mm,18*mm],repeatRows=1)
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#174552')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#cbd5d9')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f4f7f8')]),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
story += [t,Spacer(1,2*mm),P('Provisional arm actuation count: six actuator channels total (two arm-joint actuators and one gripper actuator per arm). A future powered head-tilt joint adds at least one more actuator and requires its own mechanical design. The current docking interface should not be expected to tilt while remaining directly mated.','RCall'),PageBreak()]

story += [P('3. Hand/gripper design','RH1'),P('Each hand is modeled as a palm block, two separate jaw/finger links, pivot-pin envelopes and soft rounded tips. The jaws move symmetrically in the OpenSCAD animation. The open tip-center spacing is about 22.6 mm; the closed tip-centers meet at about 5.6 mm, so the soft tips are nominally touching. With 2.8 mm radius tips, the approximate clear opening in the fully open state is 17 mm. These are geometry targets, not measured gripper capacity.','RB'),P('The hand is intended for expressive gestures and very light pinching. It is not yet a load-rated gripper: the CAD does not yet define a final servo horn, coupling link dimensions, bearing/bushing clearances, retaining hardware, finger cut-outs, contact material or force limit. Do not claim it can safely lift objects until those items are designed and tested.','RWarn'),P('4. How to view movement','RH1'),P('<b>Live kinematic concept:</b> open <font name="Courier">motion_revision_R1/AI_Desk_Companion_Motion_Animated.scad</font> in OpenSCAD. Use View → Animate and set a convenient FPS/Steps value; the $t parameter drives neutral → wave → neutral → point → nudge → neutral. The gripper opening changes throughout the cycle. To hold a fixed point, set <font name="Courier">animated = false</font> and change <font name="Courier">motion_t</font> in the source.','RB'),P('<b>Static CAD:</b> use the separate full-assembly STEP poses for neutral/open, wave left, wave right, point, nudge, reach and closed-gripper states. The individual left/right arm STEP files provide arm-only subassemblies.','RB'),P('5. Hardware/control implications','RH1'),P('A body controller such as an ESP32 can command the shoulder/elbow/gripper actuators, while the Raspberry Pi head sends high-level intents (for example WAVE_LEFT or GRIP_OPEN). The controller should translate each intent to validated joint targets, enforce per-axis bounds and speed limits, and reject overlapping or expired commands. The app should display the command state and allow cancellation.','RB'),P('Required protections include mechanical travel stops; conservative speed/current limits; safe stop on controller watchdog timeout or head/body link loss; no automatic motion restart after reconnect; and a hardware power cut for actuator power. Keep actuator power separate from the Pi logic rail and size the regulator/battery only after measured stall/transient current and thermal tests.','RB'),PageBreak()]

story += [P('6. Verification status','RH1'),P('Automated geometry check: 85 component solids in the R1 neutral assembly; 0 invalid individual solids reported by CadQuery. Nominal neutral assembly bounds are approximately 123.4 mm wide × 142.3 mm deep × 264.1 mm tall. These bounds are calculated from the current generated geometry.','RB'),P('What this check does not prove: solid intersections across every motion frame, correct hinge clearances, printable watertight parts, fastener engagement, structural stiffness, tipping margin, actuator torque, gripper force, battery runtime, thermal performance or physical safety.','RWarn')]
checks=['Replace servo placeholders with exact actuator CAD and torque/current data.','Add bore geometry, bearing/bushing clearances, shafts/retainers and a final one-servo dual-jaw linkage.','Run a collision sweep over all allowed shoulder/elbow/jaw angles; restrict any colliding states.','Calculate worst-case centre of gravity and tipping margin with asymmetric arm poses.','Validate leg, foot, shoulder mount and head-dock loads for the selected materials/manufacturing process.','Measure current draw and enclosure temperatures during continuous arm motion and computer workloads.','Prototype the gripper at low force; test pinch points, stall detection, repeatability and stop behaviour.','Keep the legs stationary unless a separate powered mobility base is deliberately designed.']
for item in checks: story.append(P('[ ] '+item,'RB'))
story += [P('7. R1 files','RH1'),P('<b>AI_Desk_Companion_CAD_and_Motion_R1.zip</b> contains the original base CAD/source, the articulated-arm revision, full-assembly STEP snapshots for named poses, left/right arm assemblies, the OpenSCAD motion source, joint/pose tables, the animated GIF and preview sheet. OpenSCAD animation and STEP snapshots describe conceptual movement; they are not motor firmware or manufacturing drawings.','RB'),P('8. Reference dimensions and hardware caveats','RH1'),P('The camera/head remains an envelope model pending vendor CAD replacement. Raspberry Pi publishes the Pi 5 mechanical design files and recommends a 5 V / 5 A USB-C power supply for the recommended high-load configuration; Camera Module 3 Wide is listed at approximately 25 × 24 × 12.4 mm. These component references do not validate the complete head assembly.','RB'),P('Official references: <link href="https://www.raspberrypi.com/products/raspberry-pi-5/" color="#16718a">Raspberry Pi 5 specifications</link>; <link href="https://www.raspberrypi.com/products/camera-module-3/" color="#16718a">Camera Module 3 specifications</link>.','RS'),Spacer(1,3*mm),P('Engineering status: R1 articulated motion concept — suitable for visual review and the next mechanical-design iteration; not cleared for manufacturing or unsupervised powered operation.','RSub')]

doc=SimpleDocTemplate(str(PDF),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=16*mm,bottomMargin=20*mm,title='AI Desk Companion CAD and Motion Engineering Report R1')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(PDF,PDF.stat().st_size)
